726: 	/* Clear fault interrupt pending. */
727: 	riscv_iommu_writel(iommu, RISCV_IOMMU_REG_IPSR, RISCV_IOMMU_IPSR_FIP);
728: 
729: 	/* Report fault events. */
730: 	do {
731: 		cnt = riscv_iommu_queue_consume(iommu, q, &idx);
732: 		if (!cnt)
733: 			break;
734: 		for (len = 0; len < cnt; idx++, len++)
735: 			riscv_iommu_fault_report(iommu, &events[idx]);
736: 		riscv_iommu_queue_release(iommu, q, cnt);
737: 	} while (1);
